-- Seed data for Coastal Eats. One restaurant group, four locations across two
-- US timezones, a week of shifts (Mon 2026-08-31 to Sun 2026-09-06), and the
-- edge cases the scheduler is meant to catch: overtime, short rest, missing
-- certification, out-of-window availability, open coverage gaps, and a swap.
--
-- Every demo account signs in with the password below.

-- Login accounts. GoTrue needs a matching row in auth.identities, so both are
-- created together for each person. Password is the same across the demo set.
do $$
declare
  account record;
  demo_password text := 'coastaleats';
begin
  for account in
    select *
    from (values
      ('a0000000-0000-0000-0000-000000000001'::uuid, 'admin@coastaleats.com'),
      ('a0000000-0000-0000-0000-000000000002'::uuid, 'manager@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000001'::uuid, 'staff@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000002'::uuid, 'noah@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000003'::uuid, 'maria@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000004'::uuid, 'james@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000005'::uuid, 'aisha@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000006'::uuid, 'diego@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000007'::uuid, 'chloe@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000008'::uuid, 'liam@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000009'::uuid, 'emma@coastaleats.com'),
      ('b0000000-0000-0000-0000-000000000010'::uuid, 'priya@coastaleats.com')
    ) as t(id, email)
  loop
      instance_id, id, aud, role, email, encrypted_password,
      email_confirmed_at, created_at, updated_at,
      raw_app_meta_data, raw_user_meta_data,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) values (
      '00000000-0000-0000-0000-000000000000',
      account.id, 'authenticated', 'authenticated', account.email,
      extensions.crypt(demo_password, extensions.gen_salt('bf')),
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}', '{}',
      '', '', '', ''
    );

      provider_id, user_id, identity_data, provider,
      last_sign_in_at, created_at, updated_at, id
    ) values (
      account.id::text, account.id,
      jsonb_build_object('sub', account.id::text, 'email', account.email, 'email_verified', true),
      'email', now(), now(), now(), gen_random_uuid()
    );
  end loop;
end $$;

